{"command": "python3 -c "
import json
import re

def fix_json(content):
    # First: fix object boundary - } followed by { needs comma after }
    content = re.sub(r'(\})\s*\n?(\s*\{)', r'\1,\n\2', content)

    # Second: fix field commas - lines ending with value (no comma) before next key
    lines = content.split('\n')
    result = []
    for i, line in enumerate(lines):
        result.append(line)
        stripped = line.strip()
        # Check if this is a key-value line ending without comma
        if stripped and not stripped.endswith(',') and ':' in stripped:
            # Check if value is at end
            # Pattern: ends with number or quoted string
            if re.search(r'[,\\s]*\"[^\"]*\"[,\\s]*$', stripped) or re.search(r'[,\\s]*\\d+[\\s]*$', stripped):
                # Look ahead for next non-empty line starting with a key
                for j in range(i+1, len(lines)):
                    next_line = lines[j].strip()
                    if next_line:
                        if next_line.startswith('\"') or next_line.startswith(\"'\"):
                            result[i] = stripped + ','
                            break
    return '\n'.join(result)

with open('/workdir/data/books.json', 'r') as f:
    content = f.read()

fixed = fix_json(content)
print('Testing parsing...')
try:
    data = json.loads(fixed)
    books = data.get('books', [])
