import json
import re

def fix_json_complete(content):
    lines = content.split('\n')
    result = []

    for i, line in enumerate(lines):
        stripped = line.strip()
        next_non_empty = None
        j = i + 1
        while j < len(lines) and not lines[j].strip():
            j += 1
        if j < len(lines):
            next_non_empty = lines[j].strip()

        line_out = line

        match = re.match(r'^\s*\"([^\"]*)\":\s*(.*)\$', stripped)
        if match:
            key = match.group(1)
            value_part = match.group(2).strip()

            if value_part not in ['[', ']', '{', '}']:
                if not stripped.endswith(','):
                    if next_non_empty is not None:
                        if next_non_empty.startswith('\"') or next_non_empty.startswith(\"'\"):
                            line_out = line.rstrip() + ','

        result.append(line_out)

    result_str = '\n'.join(result)
    result_str = re.sub(r'(\})\s*\n?(\s*\{)', r'\1,\n\2', result_str)
    return result_str

def fix_single_quotes(content):
    lines = content.split('\n')
    result = []
    for line in lines:
        def repl(m):
            return f'\"{m.group(1)}\": \"{m.group(2)}\"'
        line = re.sub(r'\"([^\"]+)\"\s*:\s*\'([^\']*)\'', repl, line)
        result.append(line)
    return '\n'.join(result)

with open('/workdir/data/books.json', 'r') as f:
